class AdaptiveTradingBrain:
    """
    O'z-o'zini o'qituvchi (Online Logistic Regression + 15,000 SMC Pattern Matrix) AI Miya.
    Har bir yangi bitimdan oldin g'alaba ehtimolini (0% - 99%) hisoblaydi va
    yopilgan har bir bitimdan (TP yoki SL) keyin og'irliklarni (weights) avtomatik yangilaydi.
    """
    def __init__(self):
        # 10 ta xususiyat: [side, has_htf, fibo_ote, fibo_ext, lon_ny, asia, rsi_norm, atr_norm, trend_align, sweep_ifvg]
        self.weights = [0.08, 0.55, 0.62, 0.35, 0.42, -0.18, 0.15, 0.12, 0.48, 0.52]
        self.bias = 0.22
        self.learning_rate = 0.045
        self.trades_learned = 0
        self.wins_learned = 0
        self.total_r_learned = 0.0
        self._pattern_index = None

    def _ensure_index(self):
        if self._pattern_index is not None:
            return
        self._pattern_index = {}
        lines = QUANT_SMC_PATTERN_MATRIX_CSV.splitlines()
        for line in lines[1:]:
            parts = line.split("|")
            if len(parts) >= 10:
                key = (parts[1], parts[5])
                if key not in self._pattern_index:
                    self._pattern_index[key] = []
                self._pattern_index[key].append(float(parts[8]))

    def predict_win_prob(self, features, side="LONG", zone_kind="IFVG", in_ote=False, rsi_val=50.0):
        self._ensure_index()
        z = self.bias
        for w, x in zip(self.weights, features):
            z += w * float(x)
        z = max(-8.0, min(8.0, z))
        logistic_prob = (1.0 / (1.0 + math.exp(-z))) * 100.0

        fibo_key = "OTE_618_705" if in_ote else "EQ_500"
        empirical_list = self._pattern_index.get((side, fibo_key), [61.5])
        empirical_prob = sum(empirical_list[:25]) / max(len(empirical_list[:25]), 1)

        blended = logistic_prob * 0.55 + empirical_prob * 0.45
        return round(min(max(blended, 35.0), 96.0), 1)

    def update_weights(self, features, is_win, realized_r=1.0):
        if not features or len(features) != len(self.weights):
            return
        target = 1.0 if is_win else 0.0
        z = self.bias + sum(w * float(x) for w, x in zip(self.weights, features))
        pred = 1.0 / (1.0 + math.exp(-max(-8.0, min(8.0, z))))
        err = (target - pred) * (1.0 + min(abs(realized_r), 3.0) * 0.25)
        for i in range(len(self.weights)):
            self.weights[i] = round(self.weights[i] + self.learning_rate * err * float(features[i]), 5)
        self.bias = round(self.bias + self.learning_rate * err, 5)
        self.trades_learned += 1
        if is_win:
            self.wins_learned += 1
        self.total_r_learned = round(self.total_r_learned + float(realized_r), 2)


