def run_embedded_deep_backtest(session_filter="ALL"):
    lines = XAUUSD_HISTORICAL_M1_VAULT_CSV.splitlines()[1:]
    total_trades = 0
    wins = 0
    losses = 0
    total_r = 0.0
    ote_wins = 0
    ote_total = 0

    for row in lines:
        cols = row.split("|")
        if len(cols) < 15 or cols[12] == "NONE":
            continue
        sess = cols[11]
        if session_filter not in ("ALL", "") and session_filter not in sess:
            continue
        r_val = float(cols[14])
        total_trades += 1
        total_r += r_val
        if r_val > 0:
            wins += 1
        else:
            losses += 1
        if "OTE" in cols[13]:
            ote_total += 1
            if r_val > 0:
                ote_wins += 1

    wr = round((wins / max(total_trades, 1)) * 100.0, 1)
    ote_wr = round((ote_wins / max(ote_total, 1)) * 100.0, 1)
    avg_r = round(total_r / max(total_trades, 1), 2)
    return (
        f"📊 <b>ICHKI 5MB KVANT BAZA — CHUQUR BACKTEST ({session_filter})</b>\n"
        f"• Tekshirilgan M1 shamchalar: <b>{len(lines):,} ta</b>\n"
        f"• Topilgan SMC + IFVG bitimlar: <b>{total_trades:,} ta</b>\n"
        f"• TP olingan (Yutuq): <b>{wins:,} ta ({wr}%)</b>\n"
        f"• SL olingan (-1R): <b>{losses:,} ta</b>\n"
        f"• Fibonacci OTE (61.8%–70.5%) aniqligi: <b>{ote_wr}% ({ote_wins}/{ote_total})</b>\n"
        f"• Jami R natija: <b>{total_r:+.1f}R</b> (O'rtacha: <b>{avg_r:+.2f}R / bitim</b>)"
    )


